SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() NOT IN (N'FastGuyDB',N'FastGuyDB_Inventory054_Test',N'FastGuyDB_Ownership058_Test') THROW 51000, '058 validator target database is not approved', 1;
IF OBJECT_ID(N'dbo.SchemaMigrationHistory',N'U') IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE migration_id='058_staff_shift_ownership') THROW 51000, '058 migration history missing', 1;
IF NOT EXISTS(SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id=c.user_type_id WHERE c.object_id=OBJECT_ID(N'dbo.Orders') AND c.name=N'staff_shift_id' AND t.name=N'int' AND c.max_length=4 AND c.is_nullable=1) THROW 51000, '058 staff_shift_id column mismatch', 1;
IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N'dbo.Orders') AND referenced_object_id=OBJECT_ID(N'dbo.WorkShift') AND name=N'FK_Orders_StaffShift' AND is_disabled=0 AND is_not_trusted=0) THROW 51000, '058 ownership foreign key missing', 1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns first_key ON first_key.object_id=i.object_id AND first_key.index_id=i.index_id AND first_key.key_ordinal=1 JOIN sys.columns first_column ON first_column.object_id=first_key.object_id AND first_column.column_id=first_key.column_id JOIN sys.index_columns second_key ON second_key.object_id=i.object_id AND second_key.index_id=i.index_id AND second_key.key_ordinal=2 JOIN sys.columns second_column ON second_column.object_id=second_key.object_id AND second_column.column_id=second_key.column_id WHERE i.object_id=OBJECT_ID(N'dbo.Orders') AND i.name=N'IX_Orders_StaffShift_Status' AND first_column.name=N'staff_shift_id' AND second_column.name=N'order_status') THROW 51000, '058 ownership index missing', 1;
IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.TR_Orders_AssignmentRoleGuard')) NOT LIKE N'%staff_shift_id must reference a STAFF shift%' THROW 51000, '058 Staff shift role guard missing', 1;
EXEC sys.sp_executesql N'IF EXISTS(SELECT 1 FROM dbo.Orders o LEFT JOIN dbo.WorkShift ws ON ws.shift_id=o.staff_shift_id LEFT JOIN dbo.Users u ON u.user_id=ws.user_id WHERE o.staff_shift_id IS NOT NULL AND (ws.shift_id IS NULL OR u.user_id IS NULL OR u.role_name<>N''STAFF'')) THROW 51000, ''058 ownership data invalid'', 1;';
PRINT '058 validation passed';
